from connected_research_case import ResearchAuthor,present_case

a=ResearchAuthor('ai-7/29')
for old,new in [('Two 45-minute sessions.','Use the three-session teaching cycle above, with extra time as needed.'),('RatesA80','Rates A 80'),('B82','B 82'),('starting79','starting 79'),('is2','is 2'),('CountsA8','Counts A 8'),('B9/15','B 9/15'),('as8','as 8'),('versus9','versus 9')]:
 if old in str(a.w):a.replace_text(old,new)
present_case(a,
 headline='Draw the comparison with honest scales and visible denominators',
 purpose='Preserve units, case counts and uncertainty limits without making a figure stand in for missing evidence.',
 intro='A chart changes how easy a difference is to see; it does not add observations. Label what the axis measures, how many cases contributed and which conditions were evaluated. For ordinary magnitude bars, a zero baseline preserves the meaning of bar length. A focused difference plot can use another clearly explained scale, but hidden truncation makes a small difference look much larger. Keep missing uncertainty missing rather than decorating a plot with invented error bars.',
 contract=[['Figure item','Complete supplied exercise contract'],['Main rates','A 80%, B 82%; raw case counts are not supplied'],['Main problematic axis','Bars start at 79% without adequate disclosure'],['Correct main difference','Two percentage points; not a several-fold increase in the actual rates'],['Separate picture','A six correct, B eight correct on the same ten cases'],['Picture axis','Correct-count axis starts at zero; denominator ten visible'],['Uncertainty','No interval or raw study design supplied; do not fabricate error bars'],['Interpretation','A clear figure does not establish sampling quality, causal advantage or population performance']],
 ledger=[['Main figure calculation','Complete value','Meaning'],['A rate','80%','Supplied rate; underlying denominator unknown'],['B rate','82%','Supplied rate; underlying denominator unknown'],['Absolute difference','82% − 80% = 2 percentage points','Correct rate-scale difference'],['Relative increase','2/80 = 2.5%','Different from two percentage points'],['Heights above hidden 79% baseline','A: 1 point; B: 3 points','Threefold drawn heights distort the actual rate ratio'],['Repair','Zero-baseline percentage bars or clearly labelled difference plot','Retain missing case-count and uncertainty information']],
 picture='The separate picture compares six versus eight correct on the same ten cases. A is 60%, B 80%; the difference is two correct or twenty percentage points. Use count bars from zero to ten and label the common ten-case denominator. If the bars secretly start at five, their visible heights are one and three, creating a threefold height ratio even though the actual count ratio is eight divided by six. The new native figure keeps main supplied percentages separate from the ten-case count example. No uncertainty bounds are supplied, and a well-labelled chart does not turn ten cases into a population or causal conclusion.',
 picture_table=[['Separate ten-case picture','A','B'],['Correct count','6','8'],['Evaluated cases','10','10'],['Observed rate','60%','80%'],['Difference','Two extra correct','Twenty percentage points'],['Zero-baseline count height','6','8'],['Hidden start-at-five height','1','3'],['Why hidden truncation misleads','Drawn heights appear threefold','Actual count ratio 8/6 is not threefold'],['Uncertainty / population inference','Not supplied','Not supplied']],
 probes=[['Figure audit','Checked interpretation'],['Main 80% versus 82%','Two percentage points, not two percent relative'],['Underlying main denominator missing','Do not invent eighty or eighty-two of one hundred cases'],['Picture counts six/eight with common ten','Show denominator and zero count baseline'],['Bar axis truncated without clear disclosure','Exaggerates relative bar lengths'],['Focused difference plot','Use an explicit difference scale and explain units'],['Uncertainty not supplied','Do not invent intervals or significance stars'],['Counts eight versus nine with different totals','Show rates and both denominators'],['Different case sets','Rate comparison alone does not prove a fair controlled advantage']],
 investigation='Perform a paper figure audit: write main rates, their two-percentage-point difference and missing denominator. Draw repaired zero-baseline percentage bars, or an explicitly labelled difference plot. Then draw the separate six/eight-of-ten count chart from zero to ten. Calculate the misleading heights above a hidden baseline of five and explain why drawn-height ratio is not actual count ratio. Keep missing uncertainty and study scope visible. No real plotting data, interval or causal advantage is invented. Reserve the unequal-denominator independent case for the first attempt.',
 teacher_key='Main 80% versus 82% differs by two percentage points, or 2.5% relative to A; raw case counts are unknown. Hidden 79% start gives drawn heights one and three, misleadingly threefold. Picture six/eight of ten gives 60%/80%, difference twenty points. Hidden start at five again produces heights one/three instead of true counts six/eight. Independent A 8/10 = 80%, B 9/15 = 60%; raw nine versus eight hides different denominators. Plot rates with totals and context. Different case sets/eligibility are not established as matched, so do not claim a controlled superiority from rates alone. No uncertainty or significance can be fabricated.',
 reference='Figures represent evidence and must preserve units, denominators, scales and uncertainty limits. Main supplied rates A 80%, B 82% differ by two percentage points, or 2.5% relative to A. Raw case counts are unknown; do not invent eighty or eighty-two cases out of one hundred. Bars starting secretly at 79% have visible heights one and three, exaggerating the actual ratio. Use zero-baseline magnitude bars or a clearly explained difference plot. Separate picture has A 6/10 = 60%, B 8/10 = 80%, difference two correct or twenty percentage points. A hidden start at five gives drawn heights one/three and misleads. Keep ten-case scope visible. No error bars or significance information are supplied. Unequal-denominator counts require rates and both totals, plus case/eligibility context; rate ordering alone does not establish a controlled or causal advantage. A polished chart does not improve sampling or add observations.',
 independent='Correct the unequal-denominator plot using both rates and totals, then state what comparison conditions remain unknown.',
 image={'type':'image','src':'/api/resource/ai-7-29-honest-axes','alt':'Two zero-baseline charts. Main supplied rates are eighty and eighty-two percent, difference two percentage points with underlying counts unknown. Separate picture shows six and eight correct of ten, difference two cases or twenty percentage points. No uncertainty intervals are supplied.','caption':'Distinct percentage and count scales with zero baselines. Labels preserve denominators and evidence limits rather than inventing a stronger result.'})
